'use strict';

// MODULES //

var isObject = require( '@stdlib/assert/is-object' );
var hasProp = require( '@stdlib/assert/has-property' );
var FieldDescriptor = require( '@stdlib/plot/vega/value/field-descriptor' );


// MAIN //

/**
* Tests whether an input value is a field descriptor instance.
*
* @param {*} value - value to test
* @returns {boolean} boolean indicating whether an input value is a field descriptor instance
*
* @example
* var FieldDescriptor = require( '@stdlib/plot/vega/value/field-descriptor' );
*
* var v = new FieldDescriptor({
*     'datum': 'price'
* });
* var bool = isValueFieldDescriptor( v );
* // returns true
*
* bool = isValueFieldDescriptor( {} );
* // returns false
*
* bool = isValueFieldDescriptor( 'foo' );
* // returns false
*/
function isValueFieldDescriptor( value ) {
	return (
		value instanceof FieldDescriptor ||

		// The following is a set of rather imperfect heuristics for handling instances originating in a different realm...
		(
			isObject( value ) &&
			(
				hasProp( value, 'datum' ) ||
				hasProp( value, 'group' ) ||
				hasProp( value, 'parent' ) ||
				hasProp( value, 'signal' )
			)
		)
	);
}


// EXPORTS //

module.exports = isValueFieldDescriptor;
